import urllib.request,re,json,pathlib,hashlib,subprocess
out=pathlib.Path('docs/mission-22-1-evidence');work=pathlib.Path('work/mission-22-1/audio');work.mkdir(parents=True,exist_ok=True)
sources=json.load(open('public/audio/sources.json'));manifest=json.load(open('public/audio/manifest.json'));text=pathlib.Path('src/audio/catalog.mjs').read_text();groups=json.loads(text.split('export const AUDIO_GROUPS=')[1].split(';\nexport const AUDIO_ASSETS=')[0]);assets=json.loads(text.split('export const AUDIO_ASSETS=')[1].rstrip(';\n'));rows=[]
for author,number,kind,duration in [('Reitanna',344001,'laugh',1.8),('qubodup',169726,'cough',.8),('khenshom',481075,'cloth',1.5)]:
 try:
  def get(url):return urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Mozilla/5.0'}),timeout=30).read()
  pageurl=f'https://freesound.org/people/{author}/sounds/{number}/';page=get(pageurl);s=page.decode();assert re.search(r'creativecommons.org/publicdomain/zero/1.0',s)
  url=re.search(r'https://cdn.freesound.org/previews/[^"\s]+-hq.mp3',s).group();raw=get(url);path=work/f'{number}.mp3';path.write_bytes(raw);(work/f'{number}.html').write_bytes(page)
  source={'id':f'fs-{number}','author':author,'title':re.search(r'<title>(.*?)</title>',s,re.S).group(1).strip(),'page':pageurl,'url':url,'license':'CC0-1.0','licenseUrl':'https://creativecommons.org/publicdomain/zero/1.0/','sha256':hashlib.sha256(raw).hexdigest(),'pageSha256':hashlib.sha256(page).hexdigest(),'attributionRequired':False,'mission':'22.1','verification':{'dateUTC':'2026-11-14','licenseEvidence':'Provider page explicitly links publicdomain/zero/1.0; HQ preview, no claim of original WAV or local recording.'}}
  sources=[s for s in sources if s['id']!=source['id']]+[source];group='village-'+kind;groups[group]=[]
  for take,offset in enumerate([0,.4] if kind=='cloth' else [0]):
   id=f'{group}-fs-{number}-{take+1}';file=id+'.flac';filters='highpass=f=150,lowpass=f=3000,alimiter=limit=0.75,volume=0.24,afade=t=in:d=0.03,afade=t=out:st='+str(duration-.08)+':d=0.08'
   subprocess.run(['ffmpeg','-y','-v','error','-ss',str(offset),'-i',str(path),'-t',str(duration),'-ac','1','-ar','32000','-af',filters,'public/audio/'+file],check=True)
   data=pathlib.Path('public/audio/'+file).read_bytes();actual=float(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration','-of','csv=p=0','public/audio/'+file]));entry={'file':file,'source':source['id'],'group':group,'duration':actual,'bytes':len(data),'sampleRate':32000,'channels':1,'provisional':False,'sha256':hashlib.sha256(data).hexdigest(),'transformations':{'source':'provider HQ MP3 preview','offset':offset,'duration':actual,'ffmpegFilters':filters,'channelPolicy':'mono 32000 Hz; nonverbal, no fabricated speech'}};manifest['assets'][id]=entry;assets[id]={k:entry[k] for k in ['file','source','duration','bytes']};groups[group].append(id)
  rows.append(source);print('OK',kind,flush=True)
 except Exception as e:rows.append({'kind':kind,'error':str(e)});print('FAIL',kind,str(e),flush=True)
manifest['independentRecordings']=len(sources);pathlib.Path('public/audio/sources.json').write_text(json.dumps(sources,indent=2)+'\n');pathlib.Path('public/audio/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');pathlib.Path('src/audio/catalog.mjs').write_text('// Generated from verified recorded sources, not synthesized loops.\nexport const AUDIO_GROUPS='+json.dumps(groups,indent=2)+';\nexport const AUDIO_ASSETS='+json.dumps(assets,separators=(',',':'))+';\n');(out/'audio-sources.json').write_text(json.dumps(rows,indent=2)+'\n')
p=pathlib.Path('public/audio/credits.html');s=p.read_text().replace('</body>','<h2>Mission 22.1 — gestes ponctuels</h2>'+''.join(f'<p><a href="{r["page"]}">{r["title"]}</a> — {r["author"]}, CC0. Préécoute HQ filtrée mono, aucune prise locale revendiquée.</p>' for r in rows if 'page' in r)+'</body>');p.write_text(s)
